let case name = List.find (fun value -> Json.string (get "name" value) = name) cases
let history raw = Json.array (get "history" raw) |> List.map Execution_data.Input_frame.of_json
let request_for request raw = match List.assoc_opt "request" (Json.object_fields raw) with
  | None -> request | Some raw -> Realization_request.of_json raw
let run request raw = K.check ~until:(N.of_json (get "until" raw)) (request_for request raw)
  (Component_assembly.of_json (get "assembly" raw)) (history raw)
let () =
  require (List.length cases = 6) "Independent component behavior fixture census changed";
  let request = Realization_request.of_json (get "request" fixture) in
  List.iter (fun raw ->
    let name = Json.string (get "name" raw) in
    let result = run request raw in
    require (E.Check_result.fingerprint result = Json.string (get "fingerprint" raw)) (name ^ ": full component behavior hash differs");
    require (Legacy_ascii.encode (E.Check_result.to_json result) = Legacy_ascii.encode (get "result" raw))
      (name ^ ": diagnostics, dependencies, coverage or counterexamples differ")) cases;
  let baseline = case "baseline" in
  let assembly = Component_assembly.of_json (get "assembly" baseline) and frames = history baseline in
  let until = N.of_json (get "until" baseline) in
  let result,usage = K.check_with_usage ~until request assembly frames in
  require (E.Check_result.outcome result = E.Pass && usage.reconstruction_work > 0 && usage.work_charged > usage.reconstruction_work)
    "Actual reconstruction or downstream shared work was omitted";
  let wrong = run request (case "wrong_behavior") in
  require (E.Check_result.outcome wrong = E.Fail && E.Check_result.counterexamples wrong <> [])
    "A coherent linked wrong implementation hid its observed behavior violations";
  let unlinked = run request (case "nonpass_link") in
  require (E.Check_result.outcome unlinked = E.Unknown &&
      List.map E.Check_diagnostic.code (E.Check_result.diagnostics unlinked) = ["component_uncovered_requirement"] &&
      E.Check_result.coverage unlinked <> [])
    "Generic link unknown was dropped or erased existing exercised behavior coverage";
  let changed = Component_assembly.of_json (set "request_fingerprint" (str (String.make 64 '0')) (Component_assembly.to_json assembly)) in
  rejected "component_behavior" (fun () -> K.check ~until request changed frames);
  let raw = Component_assembly.to_json assembly in
  let composition = get "composition" raw in
  let changed_target = get "target" composition |> set "context_version" (str "changed") in
  let changed = Component_assembly.of_json (set "composition" (set "target" changed_target composition) raw) in
  rejected "component_behavior" (fun () -> K.check ~until request changed frames);
  let numeric = case "numeric_target_equality" in
  let numeric_request = request_for request numeric in
  let numeric_assembly = Component_assembly.of_json (get "assembly" numeric) in
  let source_target = Option.get (Realization_request.target numeric_request) in
  let assembly_target = Composition.target (Component_assembly.composition numeric_assembly) in
  require (Build_request.Target.fingerprint source_target <> Build_request.Target.fingerprint assembly_target)
    "Numerically equal int/float target declarations lost their distinct exact identities";
  let raw = Component_assembly.to_json numeric_assembly in
  let composition = get "composition" raw and target = Build_request.Target.to_json assembly_target in
  let resources = get "resources" target in
  let scalar = get "fixture" resources |> set "value" (Json.Float 2.) |> set "canonical_value" (Json.Float 2.) in
  let target = set "resources" (set "fixture" scalar resources) target in
  let unequal = Component_assembly.of_json (set "composition" (set "target" target composition) raw) in
  rejected "component_behavior" (fun () -> K.check ~until numeric_request unequal frames);
  let parent = W.create ~profile:"literal.component_behavior" ~error_code:"literal_component_parent" ~maximum:50_000_000 () in
  let same,nested = K.check_with_usage ~until ~parent request assembly frames in
  require (E.Check_result.fingerprint same = E.Check_result.fingerprint result &&
      W.remaining parent = 50_000_000 - nested.work_charged && nested.work_charged = usage.work_charged)
    "One of lowering, reconstruction, behavior, linking or publication escaped the parent allowance";
  let tiny = W.create ~profile:"literal.component_behavior" ~error_code:"literal_component_parent" ~maximum:1 () in
  rejected "literal_component_parent" (fun () -> K.check ~until ~parent:tiny request assembly frames);
  List.iter (fun (code,limits) -> rejected code (fun () -> K.check ~until ~limits request assembly frames))
    ["realization_work_limit",K.make_limits ~max_work:1 ();
     "realization_input_limit",K.make_limits ~max_request_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_bytes:1 ();
     "realization_report_limit",K.make_limits ~max_report_nodes:1 ();
     "realization_monitor_limit",K.make_limits ~max_monitor_items:1 ()];
  let skeleton = Json.Object ["request",Json.Null;"assembly",Json.Null;"history",Json.Array [];"until",N.to_json until] in
  let fragments = skeleton :: Realization_request.to_json request :: Component_assembly.to_json assembly ::
      List.map Execution_data.Input_frame.to_json frames in
  let request_bytes = List.fold_left (fun total raw -> total + String.length (Canonical.encode raw) + 1) 0 fragments in
  let exact = K.check ~until ~limits:(K.make_limits ~max_request_bytes:request_bytes ()) request assembly frames in
  require (E.Check_result.fingerprint exact = E.Check_result.fingerprint result) "Exact wrapper request byte boundary changed acceptance";
  rejected "realization_input_limit" (fun () -> K.check ~until ~limits:(K.make_limits ~max_request_bytes:(request_bytes-1) ()) request assembly frames);
  let report_bytes = String.length (Legacy_ascii.encode (E.Check_result.to_json result)) + 1 in
  let exact = K.check ~until ~limits:(K.make_limits ~max_report_bytes:report_bytes ()) request assembly frames in
  require (E.Check_result.fingerprint exact = E.Check_result.fingerprint result) "Exact final ASCII report boundary changed acceptance";
  rejected "realization_report_limit" (fun () -> K.check ~until ~limits:(K.make_limits ~max_report_bytes:(report_bytes-1) ()) request assembly frames);
  let first = List.hd frames in
  let rec cyclic = first :: cyclic in
  rejected "realization_input_limit" (fun () -> K.check ~until request assembly cyclic);
  let no_model = Component_assembly.of_json (get "no_model" fixture) in
  let failed_parent = W.create ~profile:"literal.component_failure" ~error_code:"literal_failed_component_parent" ~maximum:50_000_000 () in
  rejected "component_model" (fun () -> K.check ~until ~parent:failed_parent request no_model frames);
  require (W.remaining failed_parent = 0) "Failed reconstruction left its unreported allocated work reusable";
  rejected "literal_failed_component_parent" (fun () -> K.check ~until ~parent:failed_parent request no_model frames);
  require (E.Check_result.fingerprint (K.check ~until request assembly frames) = E.Check_result.fingerprint result)
    "A failed reconstruction contaminated a fresh component behavior check";
  print_endline "actual component behavior:6 full independent Python results, coherent wrong implementation, link-result merge, authority, exact/shared bounds and repeated failed reconstruction checked"
